```ts activacion-primera-clave/src/app/ui/pages/dynamic-key-validation/dynamic-key-validation.component.ts:56-112
// Excerpt from: class DynamicKeyValidationComponent > sendKey()
sendKey() {
    this.passwordActivationService
      .passwordActivation(this.dynamicKey.value!)
      .pipe(
        tap(() => this.loaderComponent.show()),
        delay(5000),
      )
      .subscribe({
        next: (res) => {
          this.passwordActivationService.setDynamicKeyValidated(true);
          this.router.navigate(["/first-key-activation-completed"]);
        },
        error: (error) => {
          this.dynamicKey.reset();
          if (error.error) {
            this.errorCode = error.error.listErrorDto.code;
            switch (this.errorCode) {
              case "SFB002":
                this.openAlert(
                  "error",
                  "Alguno de los datos ingresados no es correcto. Por favor verifica e intenta nuevamente.",
                );
                break;
              case "SFB003":
                this.showBlockedKeyModal();
                break;
              case "SFB004":
                this.openAlert(
                  "error",
                  "No es posible continuar con el proceso. Es necesario que te comuniques con nuestra sucursal telefonica.",
                );
                setTimeout(() => {
                  this.passwordActivationService.interruptedTransaction();
                }, 3000);
                break;
              case "SFB005":
                this.openAlert(
                  "error",
                  "El proceso no pudo ser completado. Contacta a nuestra sucursal telefónica.",
                );
                setTimeout(() => {
                  this.passwordActivationService.interruptedTransaction();
                }, 3000);
                break;
              default:
                this.openAlert("error", "Ha ocurrido un error inesperado");
                break;
            }
          } else {
            this.openAlert("error", "Ha ocurrido un error inesperado");
          }
        },
        complete: () => {
          this.loaderComponent.hide();
        },
      });
  }
```

Para hacer que una suscripción se demore 5 segundos antes de ejecutarse en un entorno de programación reactiva como RxJS (Reactive Extensions for JavaScript), puedes utilizar el operador `delay` junto con `of` para crear un observable que emita un valor después de un retraso. Aquí tienes un ejemplo de cómo hacerlo:

```javascript
import { of } from 'rxjs';
import { delay } from 'rxjs/operators';

// Crear un observable que emite un valor después de 5 segundos
const delayedObservable = of('Hello, world!').pipe(
  delay(5000) // 5000 milisegundos = 5 segundos
);

// Suscribirse al observable
delayedObservable.subscribe(value => {
  console.log(value); // Esto se ejecutará después de 5 segundos
});
```

En este ejemplo, el observable `delayedObservable` emitirá el valor `'Hello, world!'` después de un retraso de 5 segundos. La suscripción al observable se ejecutará después de que el retraso haya pasado.

