```ts activacion-primera-clave/src/app/ui/pages/dynamic-key-validation/dynamic-key-validation.component.ts
import { delay, tap, timer } from "rxjs";
import { Router } from "@angular/router";
import { FormControl } from "@angular/forms";
import { Component, ViewChild, inject } from "@angular/core";

import { BcAlertComponent } from "@bancolombia/design-system-web/bc-alert";
import { BcModalComponent } from "@bancolombia/design-system-web/bc-modal";
import { BcDialogService } from "@bancolombia/design-system-web/bc-services";

import { LoaderComponent } from "../../components/loader/loader.component";
import { PasswordActivationService } from "../../../core/services/password-activation.service";

@Component({
  selector: "app-dynamic-key-validation",
  templateUrl: "./dynamic-key-validation.component.html",
  styleUrls: ["./dynamic-key-validation.component.css"],
})
export class DynamicKeyValidationComponent {
  @ViewChild(BcModalComponent, { static: false })
  BcModalEx!: BcModalComponent;

  @ViewChild("wrongKeyModal", { static: false })
  wrongKeyModal!: BcModalComponent;

  @ViewChild("blockedKeyModal", { static: false })
  blockedKeyModal!: BcModalComponent;

  @ViewChild("loaderComponent", { static: true })
  loaderComponent!: LoaderComponent;

  private router = inject(Router);
  private dialogService = inject(BcDialogService);
  private passwordActivationService = inject(PasswordActivationService);

  // @HostListener('window:beforeunload', ['$event'])
  // unloadNotification($event: any) {
  //   $event.returnValue = true;
  // }

  numInputs: number = 6;
  dynamicKey = new FormControl("");

  errorCode = "";

  /**
   * Inputs for the BcModal.
   */
  action = false;
  subTitle = "";
  typeIcon = "";
  closeModal = false;
  titleAlign = "";
  selectedValue = "";
  buttonAlignment = "horizontal";

  sendKey() {
    this.loaderComponent.show();
    this.passwordActivationService
      .passwordActivation(this.dynamicKey.value!)
      .pipe(tap(() => this.loaderComponent.show()))
      .subscribe({
        next: (res) => {
          this.passwordActivationService.setDynamicKeyValidated(true);
          this.router.navigate(["/first-key-activation-completed"]);
        },
        error: (error) => {
          this.dynamicKey.reset();
          if (error.error) {
            this.errorCode = error.error.listErrorDto.code;
            switch (this.errorCode) {
              case "SFB002":
                this.openAlert(
                  "error",
                  "Alguno de los datos ingresados no es correcto. Por favor verifica e intenta nuevamente.",
                );
                break;
              case "SFB003":
                this.showBlockedKeyModal();
                break;
              case "SFB004":
                this.openAlert(
                  "error",
                  "No es posible continuar con el proceso. Es necesario que te comuniques con nuestra sucursal telefonica.",
                );
                break;
              case "SFB005":
                this.openAlert(
                  "error",
                  "El proceso no pudo ser completado. Contacta a nuestra sucursal telefónica.",
                );
                break;
              default:
                this.openAlert("error", "Ha ocurrido un error inesperado");
                break;
            }
          } else {
            this.openAlert("error", "Ha ocurrido un error inesperado");
          }
        },
        complete: () => {
          this.loaderComponent.hide();
        },
      });
  }

  openAlert(type: string, text: string) {
    const dialogRef = this.dialogService.open(BcAlertComponent, {
      type: type,
      title: "Error",
      text: text,
      timeout: 10000,
    });

    dialogRef.onResult().subscribe(
      (closed) => {},
      (dismissed) => {
        alert("dismissed");
      },
      () => {},
    );
  }

  /**
   * Handles buttons press events (Buttons inside the modal).
   * @param event - The event number.
   */
  onPressButton(event: number) {
    if (event === 1) {
      if (this.errorCode === "SFB003") {
        this.passwordActivationService.interruptedTransaction();
        this.BcModalEx.shutDown();
      }
    } else if (event === 0) {
      this.BcModalEx.shutDown();
    }
  }

  cancelProcess() {
    this.passwordActivationService.interruptedTransaction();
  }

  showSuccessModal() {
    this.BcModalEx.openModal();
  }

  showWrongKeyModal() {
    this.wrongKeyModal.openModal();
  }

  showBlockedKeyModal() {
    this.blockedKeyModal.openModal();
  }

  closeModalEvent(event: Event) {
    this.passwordActivationService.interruptedTransaction();
  }
}
